local ActivityCakeShopMainLineDetailsDialog = Class("ActivityCakeShopMainLineDetailsDialog")
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
local CellNodePath = 'Game.UI.ActivityCakeShopDialog.Cell.ActivityCakeShopMainLineCell'
local TaskCellNodeName = 'Cell'
local FontStyleButton = CS.Game.Native.Common.FontStyleButton
local URPCameraController = CS.Game.Native.URP.URPCameraController.Instance
local UINavigationBarRoot = CS.UINavigationBarRoot
local ChapterUtils = import('Game.Chapter.ChapterUtils')
local NonBreakingSpace = utf8.char(160)

function ActivityCakeShopMainLineDetailsDialog:__init()
end

function ActivityCakeShopMainLineDetailsDialog:__delete()
    self.controller = nil
end

function ActivityCakeShopMainLineDetailsDialog:Awake()
    SetListViewAction(self.ScrollView, Bind(self, self.OnUpdateLeftListCellHandler_), TaskCellNodeName)
    SetButtonAction(self.FontStyleButton,Bind(self,self.OnFontStyleButtonClick))
end

function ActivityCakeShopMainLineDetailsDialog:OnFocus(focus)

end

function ActivityCakeShopMainLineDetailsDialog:OnShow()
    self:RefreshLeftList()
end

function ActivityCakeShopMainLineDetailsDialog:RefreshLeftList()
    GameUtils.ReloadData(self.ScrollView, #self.chapterData)
    self:SelectDefault()
end

function ActivityCakeShopMainLineDetailsDialog:SelectDefault(refresh)
    local cellIndex = 1
    for i = #self.chapterData, 1 , -1 do
        local isUnLock = false
        if self.chapterData[i].unlockLevel == 0 then
            isUnLock = true
        else
            isUnLock = ActivityCakeUtils.IsPassChapter(self.chapterData[i].unlockLevel)
        end
        if isUnLock then
            cellIndex = i
            break
        end
    end

    local cellItem = self.ScrollView:GetShownItemByItemIndex(cellIndex - 1)
    if not isNull(cellItem) then
        local env = CfUtils.GetLuaScr(cellItem,CellNodePath)
        if not isNull(env) then
            env:OnBtnNodeClick()
            if refresh then
                env:RefreshLockState()
            end
        end
    end
end

function ActivityCakeShopMainLineDetailsDialog:OnInitialize()
    self.params = self.controller.Argument.parameters

    local data = ActivityCakeUtils.GetActivityCakeMgr():GetChapterDataById(self.params.questId)
    if not isNull(data) then
        self.chapterData = data
    end
end

function ActivityCakeShopMainLineDetailsDialog:OnFinalize()

end

---@param listView SuperScrollView.LoopListView2
---@param luaIndex integer
---@return SuperScrollView.LoopListViewItem2
function ActivityCakeShopMainLineDetailsDialog:OnUpdateLeftListCellHandler_(listView, luaIndex)
    local cellNode = listView:NewListViewItem(TaskCellNodeName)
    local cellData = checkTable(self.chapterData[luaIndex])
    ---@type LadderCompetionTaskRewardCellNode
    local cellEnv = CfUtils.GetLuaScr(cellNode, CellNodePath)
    if cellEnv then
        cellEnv:SetLuaIndexAndData(luaIndex,cellData)
        cellEnv:SetClickCB(Bind(self, self.OnClickLLeftListCellCallback_))
        -- init anim
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            cellEnv:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            cellEnv:PlayAnimByIdle()
        end
    end
    return cellNode
end

function ActivityCakeShopMainLineDetailsDialog:OnClickLLeftListCellCallback_(index)
    if not isNull(self.curIndex) and self.curIndex == index then
        return
    end

    if not isNull(self.curIndex) then
        local cellItem = self.ScrollView:GetShownItemByItemIndex(self.curIndex - 1)
        if not isNull(cellItem) then
            local env = CfUtils.GetLuaScr(cellItem,CellNodePath)
            if not isNull(env) then
                env:DoSelect()
            end
        end
    end
    self.curIndex = index

    local cellItem = self.ScrollView:GetShownItemByItemIndex(self.curIndex - 1)
    if not isNull(cellItem) then
        local env = CfUtils.GetLuaScr(cellItem,CellNodePath)
        if not isNull(env) then
            env:OnSelect()
        end
    end

    self:RefreshRightInfoShow()
end

function ActivityCakeShopMainLineDetailsDialog:RefreshRightInfoShow()
    local data = self.chapterData[self.curIndex]
    self.data = data
    --CfUtils.SetUISwitchImage(self.ImgType1,data.type)
    CfUtils.FillImage(self.ImgType1,data.pic)
    CfUtils.SetUISwitchImage(self.ImgType2,self.params.index)
    CfUtils.FillText(self.ChapterName,data.name)

    if CS.Engine.I18N.I18NModule.Lang ~= "en_US" and CS.Engine.I18N.I18NModule.Lang ~= "en_UK" then
        data.desc = ChapterUtils.ReplaceStr(data.desc, " ", NonBreakingSpace)
    end

    CfUtils.FillText(self.ChapterDesc,data.desc)

    CfUtils.SetActive(self.FontStyleButton.gameObject,true)
    local isPass = ActivityCakeUtils.IsPassChapter(data.id)
    if isPass then
        if  data.type == ActivityCakeUtils.ChapterType.Story or data.type == ActivityCakeUtils.ChapterType.Battle then
            self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B5",localize("回顾"))
        end
        CfUtils.SetActive(self.CommonBtnConsumePop.gameObject,false)
    else
        local isUnLock = false
        if data.unlockLevel == 0 then
            isUnLock = true
        else
            isUnLock = ActivityCakeUtils.IsPassChapter(data.unlockLevel)
        end

        if isUnLock then
            local needCost = checkNumber(data.costItem) > 0
            CfUtils.SetActive(self.CommonBtnConsumePop.gameObject,needCost)
            if needCost then
                UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, data.costItem, data.costNum)
            end
            if data.type == ActivityCakeUtils.ChapterType.Battle then
                self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B3",localize("前往"))
            elseif data.type == ActivityCakeUtils.ChapterType.Story then
                self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B3",localize("阅读"))
            end
        else
            CfUtils.SetActive(self.CommonBtnConsumePop.gameObject,false)
            self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B4")
        end
    end

    self:SetRewardShow(data.id,isPass)
end

function ActivityCakeShopMainLineDetailsDialog:SetRewardShow(id,isPass)
    local rewardsVo = ActivityCakeUtils.GetChapterMainLineRewardVo(id)
    if not isNull(rewardsVo) and table.count(rewardsVo.rewards) > 0 then
        local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
        if scr then
            scr:FreshBaseUI(rewardsVo.rewards)
            scr:SetIsGetMaskShow(isPass)
        end
        CfUtils.SetActive(self.CommonGoodsListLight.gameObject,true)
    else
        CfUtils.SetActive(self.CommonGoodsListLight.gameObject,false)
    end
end

function ActivityCakeShopMainLineDetailsDialog:OnFontStyleButtonClick()
    local isPass = ActivityCakeUtils.IsPassChapter(self.data.id)
    if isPass then
        self:EnterChapter()
    else
        local isUnLock = false
        if self.data.unlockLevel == 0 then
            isUnLock = true
        else
            isUnLock = ActivityCakeUtils.IsPassChapter(self.data.unlockLevel)
        end
        if isUnLock then
            self:EnterChapter()
        else

        end
    end
end

function ActivityCakeShopMainLineDetailsDialog:EnterChapter()
    ---@type ActivityCakeUtils
    if self.data.type == ActivityCakeUtils.ChapterType.Battle then
        self:EnterChapterBattle()
    elseif self.data.type == ActivityCakeUtils.ChapterType.Story then
        self:EnterChapterStory()
    end
end

function ActivityCakeShopMainLineDetailsDialog:EnterChapterBattle()
    local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIFightTeamChoose,
        parameters = {
            activityUuid = activityData.id,
            levelId = self.data.id
        }
    }, {
        { id = self.controller.Argument.id }
    })
end

function ActivityCakeShopMainLineDetailsDialog:EnterChapterStory()
    local storyVo = ActivityCakeUtils.GetChapterVo(self.data.id)
    if not isNull(storyVo) then
        local chapterId = storyVo.plotIdStory
        ChapterUtils.ProcessChapter(checkNumber(chapterId), function(go)
            self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
            URPCameraController:SetMainCameraActive(false)
            UINavigationBarRoot.Instance:SetActive(false)
            self._plotGo = go
        end, function()
            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            URPCameraController:SetMainCameraActive(true)
            UINavigationBarRoot.Instance:SetActive(true)
            self:OnStoryEnd()
            CfUtils.SafeDelete(self._plotGo)
        end)
    end
end

function ActivityCakeShopMainLineDetailsDialog:OnStoryEnd()
    local isPass = ActivityCakeUtils.IsPassChapter(self.data.id)
    if isPass then
        return
    end
    local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
    GameUtils.Request(Interfaces.OverseaActivityCatParadisePlot, {activityUuid = activityData.id,questId = self.data.id }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            ActivityCakeUtils.GetActivityCakeMgr():UpdateChapterInfo(responseData)
            local isPassChapter = ActivityCakeUtils.GetActivityCakeMgr():IsPassChapterNode(self.params.questId)
            if #responseData.rewards > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards, cb = function()
                    if isPassChapter then
                        UIModule.BackDialog()
                    else
                        self:OnFinishStory()
                    end
                end } })
            else
                if isPassChapter then
                    UIModule.BackDialog()
                else
                    self:OnFinishStory()
                end
            end
        end
    end)
end

function ActivityCakeShopMainLineDetailsDialog:OnFinishStory()
    if not isNull(self.curIndex) then
        local cellItem = self.ScrollView:GetShownItemByItemIndex(self.curIndex - 1)
        if not isNull(cellItem) then
            local env = CfUtils.GetLuaScr(cellItem,CellNodePath)
            if not isNull(env) then
                env:DoSelect()
                env:RefreshIsPass()
            end
        end
    end
    self:SelectDefault(true)
end

return ActivityCakeShopMainLineDetailsDialog